def __recover_child_process_weights(self, model, best_path, last_path):
    # transfer back the best path to the trainer
    if self.trainer.checkpoint_callback:
        self.trainer.checkpoint_callback.best_model_path = best_path
    # todo, pass also best score

    # load last weights
    if last_path is not None and not self.trainer.testing:
        ckpt = torch.load(last_path, map_location=lambda storage, loc: storage)
        model.load_state_dict(ckpt)

    self.trainer.model = model

def activation(data: mx.sym.Symbol, act_type: str) -> mx.sym.Symbol:
    """
    Apply custom or standard activation.

    Custom activation types include:
     - Swish-1, also called Sigmoid-Weighted Linear Unit (SiLU): Ramachandran et
       al. (https://arxiv.org/pdf/1710.05941.pdf), Elfwing et al.
       (https://arxiv.org/pdf/1702.03118.pdf)
     - Gaussian Error Linear Unit (GELU): Hendrycks and Gimpel
       (https://arxiv.org/pdf/1606.08415.pdf)

    :param data: input Symbol of any shape.
    :param act_type: Type of activation.
    :return: output Symbol with same shape as input.
    """
    # TODO: Contribute these to MXNet?  For now it appears that registered activation types must be implemented in C++.
    if act_type == C.SWISH1:
        return data * mx.sym.Activation(data, act_type="sigmoid")
    elif act_type == C.GELU:
        # Approximation of x * gaussian_cdf(x) used by Hendrycks and Gimpel
        return 0.5 * data * (1 + mx.sym.Activation((math.sqrt(2 / math.pi) * (data + (0.044715 * (data**3)))),
                                                   act_type="tanh"))
    else:
        return mx.sym.Activation(data, act_type=act_type)

def _get_agent(self, participant):
    dbid = participant.get('identifier')
    text = participant.get('entity_text')[0]

    if dbid == 'GENERIC':
        if not text:
            return None
        else:
            return Agent(text)

    db_refs = {}
    entity_type = participant.get('entity_type')
    if entity_type in ['protein', 'chemical', 'gene']:
        # TODO: standardize name here
        name = participant.get('entity_text')[0]
        db_refs['TEXT'] = text
        if dbid:
            db_name, db_id = dbid.split(':')
            if db_name.lower() == 'uniprot':
                uniprot_id = uniprot_client.get_id_from_mnemonic(db_id)
                db_refs['UP'] = uniprot_id
            elif db_name.lower() == 'pubchem':
                chebi_id = chebi_client.get_chebi_id_from_pubchem(db_id)
                db_refs['CHEBI'] = chebi_id
            elif db_name.lower() == 'hgnc':
                db_refs['HGNC'] = db_id
    elif entity_type == 'protein_family':
        name = text
    else:
        return None
    # TODO: handle other participant types
    agent = Agent(name, db_refs=db_refs)

    features = participant.get('features')
    if features:
        for feature in features:
            feature_type = feature.get('feature_type')
            if feature_type == 'modification_feature':
                mc = self._get_mod_condition(feature)
                agent.mods.append(mc)
            elif feature_type == 'binding_feature':
                bc = self._get_bound_condition(feature)
                agent.bound_conditions.append(bc)
            elif feature_type == 'mutation_feature':
                mc = self._get_mut_condition(feature)
                agent.mutations.append(mc)
            elif feature_type == 'location_feature':
                agent.location = feature.get('location')
    not_features = participant.get('features')
    if not_features:
        for feature in not_features:
            feature_type = feature.get('feature_type')
            if feature_type == 'modification_feature':
                mc = self._get_mod_condition(feature)
                mc.is_modified = False
                agent.mods.append(mc)
            elif feature_type == 'binding_feature':
                bc = self._get_bound_condition(feature)
                bc.is_bound = False
                agent.bound_conditions.append(bc)
    return agent

