def __call__(self, fields, initial_annotations=None):
    start = time.perf_counter()
    if not initial_annotations:
        initial_annotations = []
    LOG.debug('initial annotations = %d', len(initial_annotations))

    if self.debug_visualizer:
        for stride, pif_i in zip(self.field_config.cif_strides, self.field_config.cif_indices):
            self.debug_visualizer.pif_raw(fields[pif_i], stride)
        for stride, paf_i in zip(self.field_config.caf_strides, self.field_config.caf_indices):
            self.debug_visualizer.paf_raw(fields[paf_i], stride)

    pifhr = PifHr(self.field_config).fill(fields)
    seeds = PifSeeds(pifhr.accumulated, self.field_config).fill(fields)
    # TODO make paf_scored not part of self?
    self.paf_scored = PafScored(pifhr.accumulated, self.field_config, self.skeleton).fill(fields)
    # pif init
    if self.debug_visualizer:
        self.debug_visualizer.pifhr(pifhr.accumulated)

    occupied = Occupancy(pifhr.accumulated.shape, 2, min_scale=4)
    annotations = []

    def mark_occupied(ann):
        for joint_i, xyv in enumerate(ann.data):
            if xyv[2] == 0.0:
                continue

            width = ann.joint_scales[joint_i]
            occupied.set(joint_i, xyv[0], xyv[1], width)

    for ann in initial_annotations:
        self._grow(ann)
        annotations.append(ann)
        mark_occupied(ann)

    for v, f, x, y, s in seeds.get():
        if occupied.get(f, x, y):
            continue

        ann = Annotation(self.keypoints, self.out_skeleton).add(f, (x, y, v))
        ann.joint_scales[f] = s
        self._grow(ann)
        annotations.append(ann)
        mark_occupied(ann)

    if self.debug_visualizer:
        self.debug_visualizer.occupied(occupied)

    LOG.debug('annotations %d, %.3fs', len(annotations), time.perf_counter() - start)

    if self.force_complete:
        annotations = self.complete_annotations(pifhr, fields, annotations)

    return annotations

def process_data(model, x=None, data=None, name='x'):
    """Process and validate just the x data"""

    # Ensure we were passed a model object
    # TODO

    # Use training data if none passed
    if x is None:
        try:
            x = model._train[name]
        except AttributeError:
            raise RuntimeError(name+' cannot be None if model is not fit')

    # Numpy arrays
    if data is None:

        # Ensure data is numpy array
        if not isinstance(x, np.ndarray):
            raise TypeError(name+' must be a numpy ndarray')

    else:

        # Pandas DataFrame
        from pandas import DataFrame
        if isinstance(data, DataFrame):

            # Check type
            if not isinstance(x, (int, str, list)):
                raise TypeError(name+' must be an int, string, or list')
            if isinstance(x, list):
                if not all([isinstance(e, (int, str)) for e in x]):
                    raise TypeError(name+' must be a list of int or str')

            # Get the columns
            x = data.ix[:,x].values

        else:
            raise TypeError('data must be None or a pandas DataFrame')

    # Make data at least 2 dimensional (0th dim should be N)
    if x.ndim == 1:
        x = np.expand_dims(x, 1)

    # TODO: ensure x data shape matches model._ph['x'] shape (only if fit)

    return x

def unify(self, typingctx, other):
    if isinstance(other, SeriesType):
        new_index = types.none
        if self.index != types.none and other.index != types.none:
            new_index = self.index.unify(typingctx, other.index)
        elif other.index != types.none:
            new_index = other.index
        elif self.index != types.none:
            new_index = self.index

        # If dtype matches or other.dtype is undefined (inferred)
        if other.dtype == self.dtype or not other.dtype.is_precise():
            return SeriesType(
                self.dtype,
                self.data.unify(typingctx, other.data),
                new_index)

    # XXX: unify Series/Array as Array
    return super(SeriesType, self).unify(typingctx, other)

def get_optimizer_fun_tf2(optimizer_type):
    optimizer_type = optimizer_type.lower()
    if (
            optimizer_type == 'sgd' or
            optimizer_type == 'stochastic_gradient_descent' or
            optimizer_type == 'gd' or
            optimizer_type == 'gradient_descent'
    ):
        return tf.keras.optimizers.SGD()
    elif optimizer_type == 'adam':
        return tf.keras.optimizers.Adam()
    elif optimizer_type == 'adadelta':
        return tf.keras.optimizers.Adadelta()
    elif optimizer_type == 'adagrad':
        return tf.keras.optimizers.Adagrad()
    elif optimizer_type == 'adagradda':
        return None # tf.train.AdagradDAOptimizer  todo appears tf.keras.optimizers does not support
    elif optimizer_type == 'momentum':
        return None # tf.train.MomentumOptimizer  todo appears tf.keras.optimizers does not support
    elif optimizer_type == 'ftrl':
        return tf.keras.optimizers.Ftrl()
    elif optimizer_type == 'proximalgd':
        return None #tf.train.ProximalGradientDescentOptimizer todo appears tf.keras.optimizers does not support
    elif optimizer_type == 'proximaladagrad':
        return None #tf.train.ProximalAdagradOptimizer todo appears tf.keras.optimizers does not support
    elif optimizer_type == 'rmsprop':
        return tf.keras.optimizers.RMSprop()
    else:
        raise ValueError('Invalid optimizer_type: ' + optimizer_type)

def assert_trained(post_model, loss):
    post_weights = [param.clone() for param in post_model.parameters()]
    if loss == 0:
        # TODO if without momentum, weights should not change too
        for p_name, param in post_model.named_parameters():
            assert param.grad.norm() == 0
    else:
        assert not all(torch.equal(w1, w2) for w1, w2 in zip(pre_weights, post_weights)), 'Model parameter is not updated in training_step(), check if your tensor is detached from graph.'
        min_norm = 0
        max_norm = 1e5
        for p_name, param in post_model.named_parameters():
            try:
                assert min_norm < param.grad.norm() < max_norm, f'Gradient norm fails the extreme value check {min_norm} < {p_name}:{param.grad.norm()} < {max_norm}, which is bad. Loss: {loss}. Check your network and loss computation. Consider using the "clip_grad" and "clip_grad_val" net parameter.'
            except Exception as e:
                logger.warn(e)
    logger.debug('Passed network weight update assertation in dev lab_mode.')

@bound_function("series.append")
def resolve_append(self, ary, args, kws):
    # TODO: ignore_index
    assert not kws
    arr_typ = if_series_to_array_type(ary)
    other, = args
    if isinstance(other, (SeriesType, types.Array)):
        all_arrs = types.Tuple((arr_typ, if_series_to_array_type(other)))
    elif isinstance(other, types.BaseTuple):
        all_arrs = types.Tuple((arr_typ, *[if_series_to_array_type(a) for a in other.types]))

    # TODO: list
    # call np.concatenate to handle type promotion e.g. int, float -> float
    ret_typ = self.context.resolve_function_type(np.concatenate, (all_arrs,), kws).return_type
    ret_typ = if_arr_to_series_type(ret_typ)
    return signature(ret_typ, *args)

def compare_text_approximate(x, y):
    # Fast cutoff when one is empty
    if bool(x) != bool(y):
        return False

    if isinstance(x, list):
        x = "".join(x)
    if isinstance(y, list):
        y = "".join(y)

    # TODO: Review whether this is wanted.
    #       The motivation is to align tiny
    #       strings in outputs such as a single number.
    # Allow aligning short strings without comparison
    nx = len(x)
    ny = len(y)
    shortlen = 10  # TODO: Add this to configuration framework
    if nx < shortlen and ny < shortlen:
        return True

    return compare_strings_approximate(x, y, threshold=0.7)

def get_json_validator(schema):
    # We're using a helper function here to make it easier to change the
    # validator that's used (e.g. different draft implementation), without
    # having to change it all across the codebase.
    # TODO: replace with (stable) Draft6Validator, if available
    if jsonschema is None:
        raise ValueError(Errors.E136)
    return jsonschema.Draft4Validator(schema)

@property
def num_frames(self):
    """Number of frames."""
    # TODO: add a complete frame_size, to cover the whole audio signal?
    # modifications to signal_frame() needed
    #return int(np.ceil(((np.shape(self.signal)[0]) + self.frame_size) / self.hop_size))
    return int(np.ceil((np.shape(self.signal)[0]) / self.hop_size))
